  ('de', 'HomePage', 'dayBody', 'Verlässlicher Rhythmus, Platz zum Kindsein. So sehen neun Stunden tatsächlich aus.'),
  ('de', 'HomePage', 'dayHeading', 'Ein Tag bei Willow Grove'),
  ('de', 'HomePage', 'heroBody', 'Eine kleine, lizenzierte Einrichtung in {neighborhood}, in der dieselben Bezugspersonen Ihr Kind jeden Morgen begrüßen und Ihnen genau sagen können, wie sein Tag war.'),
  ('de', 'HomePage', 'heroEyebrow', 'Lizenzierte Kinderbetreuung · Alter {ageRange}'),
  ('de', 'HomePage', 'heroHeading', 'Ein Ort, an dem Ihr Kind beim Namen gekannt wird.'),
  ('de', 'HomePage', 'infantsBlurb', 'Eine feste Bezugsperson pro Kind, damit Fläschchen, Schlaf und erste Wörter von jemandem verfolgt werden, der Ihr Baby kennt — nicht von dem, der gerade frei ist.'),
  ('de', 'HomePage', 'mapLabel', 'Karte von {neighborhood}'),
  ('de', 'HomePage', 'metaDescription', 'Eine kleine, lizenzierte Kindertagesstätte in Northwest Portland für Kinder von 6 Wochen bis 5 Jahren, in der dieselben Bezugspersonen Ihr Kind beim Namen kennen. Rufen Sie an und planen Sie einen Besuch.'),
  ('de', 'HomePage', 'metaTitle', 'Willow Grove Children''s Center · Lizenzierte Kinderbetreuung in NW Portland'),
  ('de', 'HomePage', 'planVisit', 'Besuch planen'),
  ('de', 'HomePage', 'preschoolBlurb', 'Erste Schrift, Zahlen und die schwierigere Arbeit des Abwartens und des Benennens von Gefühlen — die Grundlage für die Grundschule.'),
  ('de', 'HomePage', 'programsHeading', 'Programme nach Alter'),
  ('de', 'HomePage', 'staffHeading', 'Die Menschen, die Ihr Kind kennen werden'),
  ('de', 'HomePage', 'testimonialAttribution', 'Priya R., Mutter eines Kindes aus der Säuglingsgruppe'),
  ('de', 'HomePage', 'testimonialHeading', 'Von einer Mutter'),
  ('de', 'HomePage', 'testimonialQuote', '„Am dritten Tag sagte mir Aisha, dass meine Tochter nur einschläft, wenn sie den blauen Elefanten halten kann. Das hatte ich niemandem erzählt. Da hörte ich auf, mir Sorgen zu machen.“'),
  ('de', 'HomePage', 'toddlersBlurb', 'Platz zum Bewegen und Sprache überall. Die Tage sind vorhersehbar, damit ein Kleinkind, das die Welt lernt, sich darauf verlassen kann, was als Nächstes kommt.'),
  ('de', 'HomePage', 'trustInfantRatio', 'Schlüssel Säuglinge'),
  ('de', 'HomePage', 'trustOpenWeekdays', 'Werktags geöffnet'),
  ('de', 'HomePage', 'trustStateLicense', 'Staatliche Lizenz'),
  ('de', 'HomePage', 'trustYearsCaring', 'Für Familien da'),
  ('de', 'HomePage', 'visitHeading', 'Kommen Sie und sehen Sie selbst'),
  ('de', 'HomePage', 'yearsValue', '{years} Jahre'),
  ('de', 'Nav', 'about', 'Über uns'),
  ('de', 'Nav', 'contact', 'Kontakt'),
  ('de', 'Nav', 'faq', 'FAQ'),
  ('de', 'Nav', 'home', 'Willow Grove Startseite'),
  ('de', 'Nav', 'programs', 'Programme'),
  ('de', 'Nav', 'staff', 'Team'),
  ('de', 'Nav', 'tuition', 'Gebühren'),
  ('de', 'Programs', 'infants', 'Säuglinge'),
  ('de', 'Programs', 'infantsAges', '6 Wochen – 15 Monate'),
  ('de', 'Programs', 'infantsGroupSize', '8 Kinder'),
  ('de', 'Programs', 'preschool', 'Vorschule'),
  ('de', 'Programs', 'preschoolAges', '3 – 5 Jahre'),
  ('de', 'Programs', 'preschoolGroupSize', '18 Kinder'),
  ('de', 'Programs', 'toddlers', 'Kleinkinder'),
  ('de', 'Programs', 'toddlersAges', '15 Monate – 3 Jahre'),
  ('de', 'Programs', 'toddlersGroupSize', '10 Kinder'),
  ('de', 'ProgramsPage', 'dayBody', 'Jede Gruppe folgt demselben Rhythmus, dem Alter angepasst. Säuglinge schlafen und essen darin nach ihrem eigenen Plan; ältere Kinder gehen gemeinsam hindurch.'),
  ('de', 'ProgramsPage', 'dayHeading', 'Ein Tag bei Willow Grove'),
  ('de', 'ProgramsPage', 'eyebrow', 'Alter {ageRange}'),
  ('de', 'ProgramsPage', 'factAges', 'Alter'),
  ('de', 'ProgramsPage', 'factGroup', 'Gruppengröße'),
  ('de', 'ProgramsPage', 'factRatio', 'Schlüssel'),
  ('de', 'ProgramsPage', 'heading', 'Programme nach Alter'),
  ('de', 'ProgramsPage', 'infantsDetail', 'Jedes Baby bekommt eine feste Bezugsperson, die Fläschchen, Schlaf und Wickeln übernimmt. Das ist die Person, die lernt, dass Ihre Tochter nur mit dem blauen Elefanten einschläft, und die Ihnen beim Abholen davon erzählt.'),
  ('de', 'ProgramsPage', 'infantsStaffing', 'Essen und Schlaf richten sich nach dem Rhythmus Ihres Babys, nicht nach dem der Gruppe. Sie bekommen den Tag aufgeschrieben — jedes Fläschchen, jeden Schlaf, jede Windel — bevor Sie am Auto sind.'),
  ('de', 'ProgramsPage', 'intro', 'Drei Gruppen in einem Haus und dieselben Gesichter von der Säuglingsgruppe bis zu dem Morgen, an dem Ihr Kind in die Grundschule geht. Hier steht, wer in welcher Gruppe ist, wie viele Kinder betreut werden und was der Tag bereithält.'),
  ('de', 'ProgramsPage', 'metaDescription', 'Gruppen für Säuglinge, Kleinkinder und Vorschulkinder in Northwest Portland — Betreuungsschlüssel, Gruppengrößen und wie ein Tag in jeder Gruppe wirklich aussieht.'),
  ('de', 'ProgramsPage', 'metaTitle', 'Programme'),
  ('de', 'ProgramsPage', 'preschoolDetail', 'Erste Schrift und Zahlen — und der schwierigere Lehrplan darunter: abwarten, teilen, sagen was man fühlt, statt etwas zu werfen. Das ist die Grundlage, mit der die Grundschule rechnet.'),
  ('de', 'ProgramsPage', 'preschoolStaffing', 'Jeden Morgen Kleingruppenarbeit, geleitet von einer Fachkraft, die diese Gruppe seit Jahren unterrichtet. Im Frühjahr schreiben wir an die Grundschule Ihres Kindes, damit die erste Lehrkraft es schon kennt.'),
  ('de', 'ProgramsPage', 'toddlersDetail', 'Das Jahr, in dem ein Kind lernt, dass die Welt eine Ordnung hat. Die Tage sind bewusst vorhersehbar, damit ein Kleinkind, das die Uhr noch nicht lesen kann, trotzdem weiß, was als Nächstes kommt — und die Sprache hört nie auf: benennen, erzählen, fragen.'),
  ('de', 'ProgramsPage', 'toddlersStaffing', 'Zwei Fachkräfte bleiben das ganze Jahr in dieser Gruppe. Das Sauberwerden geschieht im Tempo Ihres Kindes und im Einklang mit dem, was Sie zu Hause tun, nie nach einer Frist, die wir setzen.'),
  ('de', 'ProgramsPage', 'visitAria', 'Besuch planen'),
  ('de', 'ProgramsPage', 'visitBody', 'Rufen Sie im Büro an, und Sie bekommen eine klare Auskunft darüber, welche Gruppen Platz haben und wie lang die Wartezeit für die anderen ist — und dann kommen Sie und stellen sich in den Raum, in dem Ihr Kind tatsächlich wäre.'),
  ('de', 'ProgramsPage', 'visitHeading', 'Unsicher, welche Gruppe passt?'),
  ('de', 'Staff', 'aishaBio', 'Acht Jahre in der Säuglingsgruppe, und noch nie hat sie Eltern ein Tagesblatt in die Hand gedrückt, bei dem sie raten musste. Sie ist der Grund, warum wir Ihnen sagen können, auf welcher Seite Ihre Tochter lieber gehalten wird.'),
  ('de', 'Staff', 'aishaRole', 'Leitung Säuglingsgruppe'),
  ('de', 'Staff', 'danielBio', 'Verbringt seinen Tag damit, die Welt Menschen zu erklären, die gerade entdeckt haben, dass sie Wörter hat. Das Sauberwerden geschieht bei ihm, im Tempo Ihres Kindes, und er wird Ihnen nie das Gefühl geben, im Rückstand zu sein.'),
  ('de', 'Staff', 'danielRole', 'Leitung Kleinkindgruppe'),
  ('de', 'Staff', 'graceBio', 'Kam von einer Neugeborenenstation im Krankenhaus zu uns, was man daran merkt, wie sie mit einem Baby umgeht, das nicht zur Ruhe kommt. Sie hat die ruhigsten Hände im Haus, und der Raum ist dadurch leiser.'),
  ('de', 'Staff', 'graceRole', 'Erzieherin Säuglingsgruppe'),
  ('de', 'Staff', 'mariaBio', 'Führt das Haus und übernimmt immer noch die Säuglingsgruppe, wenn jemand krank ist. Sie ist die Person, zu der Sie durchgestellt werden, wenn Sie anrufen, und die Ihnen offen sagt, wenn für die gewünschte Gruppe neun Monate Wartezeit bestehen.'),
  ('de', 'Staff', 'mariaRole', 'Leiterin'),
  ('de', 'Staff', 'nadiaBio', 'Kümmert sich um Anmeldungen, die Warteliste und jedes Formular, das die Behörde verlangt. Wenn Ihnen anderswo je eine vage Auskunft über Gebühren gegeben wurde, ist sie die Korrektur dazu.'),
  ('de', 'Staff', 'nadiaRole', 'Stellvertretende Leiterin'),
  ('de', 'Staff', 'sofiaBio', 'Kocht jede Mahlzeit im Haus, weshalb wir bei Allergien genau sein können statt nur hoffnungsvoll. Sie weiß, welche Kinder Gemüse nur essen, wenn es auf eine bestimmte Art geschnitten ist, und schneidet es genau so.'),
  ('de', 'Staff', 'sofiaRole', 'Köchin'),
  ('de', 'Staff', 'tenure', 'seit {years} Jahren bei Willow Grove'),
  ('de', 'Staff', 'tomBio', 'Leitet jeden Morgen die Kleingruppenarbeit und schreibt im Frühjahr an die Grundschule jedes Kindes, damit die erste Lehrkraft es schon kennt. Sechs Jahre in derselben Gruppe.'),
  ('de', 'Staff', 'tomRole', 'Leitung Vorschulgruppe'),
  ('de', 'StaffPage', 'eyebrow', '{count} Personen im Team'),
  ('de', 'StaffPage', 'factChecksLabel', 'Jede Einstellung'),
  ('de', 'StaffPage', 'factChecksValue', 'Führungszeugnis geprüft, Erste Hilfe und Reanimation aktuell'),
  ('de', 'StaffPage', 'factLongestLabel', 'Am längsten bei uns'),
  ('de', 'StaffPage', 'factTeamLabel', 'Personen im Team'),
  ('de', 'StaffPage', 'factTenureLabel', 'Durchschnittlich bei uns'),
  ('de', 'StaffPage', 'heading', 'Die Menschen, die Ihr Kind kennen werden'),
  ('de', 'StaffPage', 'intro', 'Die Führung erzählt Ihnen etwas über das Gebäude. Diese Seite erzählt Ihnen etwas über die Menschen darin, denn ein Raum ist nur so verlässlich wie die Person, die darin steht — und wie lange sie geblieben ist, kann keine Broschüre erfinden.'),
  ('de', 'StaffPage', 'metaDescription', 'Die Erzieherinnen, Erzieher und Mitarbeitenden einer lizenzierten Kindertagesstätte in Northwest Portland — wer sie sind, wie lange sie schon hier sind und warum das die Zahl zum Vergleichen ist.'),
  ('de', 'StaffPage', 'metaTitle', 'Team'),
  ('de', 'StaffPage', 'stayBody', 'Personalwechsel ruiniert eine Einrichtung leise, und auf einer Website wird er fast nie erwähnt. Hier steht, was wir dagegen tun, damit Sie der nächsten Einrichtung dieselben drei Fragen stellen können.'),
  ('de', 'StaffPage', 'stayHeading', 'Warum Menschen bleiben'),
  ('de', 'StaffPage', 'stayHiringBody', 'Eine offene Stelle wird von der Leitung und der stellvertretenden Leitung abgedeckt, statt schnell besetzt zu werden. Bei jeder Einstellung liegt vor dem ersten Tag mit Kindern ein Führungszeugnis vor, ohne Ausnahmen für volle Wochen.'),
  ('de', 'StaffPage', 'stayHiringTitle', 'Absichtlich langsam bei Einstellungen'),
  ('de', 'StaffPage', 'stayPayBody', 'Unsere Fachkräfte verdienen mehr als in den Einrichtungen um uns herum, und die Bezahlung steigt mit der Zeit hier statt mit einem Titel. Das ist der größte Posten auf unserer Kostenaufstellung und der Grund, warum die Gebühren sind, wie sie sind.'),
  ('de', 'StaffPage', 'stayPayTitle', 'Bewusst über dem üblichen Satz bezahlt'),
  ('de', 'StaffPage', 'stayRoomBody', 'Niemand wird zwischen Gruppen verschoben, um eine Lücke zu stopfen. Eine Fachkraft bleibt das Jahr über bei ihrer Gruppe, und erst das macht aus einer festen Bezugsperson mehr als ein Wort auf dem Papier.'),
  ('de', 'StaffPage', 'stayRoomTitle', 'Dieselbe Gruppe, das ganze Jahr'),
  ('de', 'StaffPage', 'teamBody', 'Porträts folgen; die Initialen sind ein Platzhalter, kein Stockfoto vom Personal einer anderen Einrichtung. Alles unter jedem Namen trifft auf die Person zu, die tatsächlich im Raum stehen wird.'),
  ('de', 'StaffPage', 'teamHeading', 'Wer hier ist'),
  ('de', 'StaffPage', 'visitBody', 'Namen auf einer Seite nützen wenig. Kommen Sie vorbei, schauen Sie sich die Gruppe an, in der Ihr Kind wäre, und sehen Sie, ob die Person darin jemand ist, bei dem Ihr Kind zur Ruhe käme.'),
  ('de', 'StaffPage', 'visitHeading', 'Kommen Sie vorbei und lernen Sie sie kennen'),
  ('de', 'StaffPage', 'yearsValue', '{years} Jahre'),
  ('de', 'TuitionPage', 'eyebrow', 'Ab {lowest} im Monat, Vollzeit'),
  ('de', 'TuitionPage', 'factDepositLabel', 'Kaution'),
  ('de', 'TuitionPage', 'factDepositValue', '{weeks} Wochen, erstattet beim Austritt'),
  ('de', 'TuitionPage', 'factIncludedLabel', 'Im Satz enthalten'),
  ('de', 'TuitionPage', 'factIncludedValue', 'Mahlzeiten, Snacks, Windeln, Feuchttücher und Sonnencreme'),
  ('de', 'TuitionPage', 'factNoticeLabel', 'Kündigungsfrist'),
  ('de', 'TuitionPage', 'factNoticeValue', '{weeks} Wochen, schriftlich'),
  ('de', 'TuitionPage', 'factRegistrationLabel', 'Anmeldung'),
  ('de', 'TuitionPage', 'factRegistrationValue', '{amount}, einmalig bei der Aufnahme'),
  ('de', 'TuitionPage', 'fiveDayBody', 'Die ganze Woche, und das einzige Modell, bei dem Ihr Kind jeden Tag dieselbe Gruppe um sich hat. Für Säuglinge empfehlen wir es, weil sie sich schneller einleben, wenn die Woche nicht ständig die Form wechselt.'),
  ('de', 'TuitionPage', 'fiveDayDays', 'Montag bis Freitag'),
  ('de', 'TuitionPage', 'fiveDayName', 'Fünf Tage'),
  ('de', 'TuitionPage', 'heading', 'Was ein Platz hier kostet'),
  ('de', 'TuitionPage', 'hiddenBody', 'Nichts davon steckt in einem Vertrag, den Sie am letzten Tag unterschreiben. Es steht hier, bevor Sie anrufen, weil die Kosten von Kinderbetreuung nicht nur die Zahl in der Tabelle sind.'),
  ('de', 'TuitionPage', 'hiddenClosuresBody', 'Gesetzliche Feiertage, dazu drei Fortbildungstage im Jahr und die Woche zwischen Weihnachten und Neujahr. Diese werden berechnet — der Satz gilt monatlich, nicht pro besuchtem Tag — und die Termine werden jeden August ein Jahr im Voraus veröffentlicht.'),
  ('de', 'TuitionPage', 'hiddenClosuresTitle', 'Tage, an denen wir geschlossen sind'),
  ('de', 'TuitionPage', 'hiddenHeading', 'Die Teile, die eine Preisliste sonst weglässt'),
  ('de', 'TuitionPage', 'hiddenHelpBody', 'Wir akzeptieren staatliche Zuschüsse und nehmen Betreuungszuschüsse von Arbeitgebern an. Nadia kümmert sich um beides und sagt Ihnen, wofür Sie voraussichtlich infrage kommen, bevor Sie irgendetwas ausfüllen — auch dann, wenn die Antwort nichts ist.'),
  ('de', 'TuitionPage', 'hiddenHelpTitle', 'Hilfe bei den Kosten'),
  ('de', 'TuitionPage', 'hiddenIncreaseBody', 'Die Sätze steigen einmal im Jahr, meist um wenige Prozent, entsprechend dem, was wir den Fachkräften zahlen. Sie bekommen es im Juni schriftlich für einen Start im September, damit niemand von einer Rechnung überrascht wird.'),
  ('de', 'TuitionPage', 'hiddenIncreaseTitle', 'Die jährliche Erhöhung'),
  ('de', 'TuitionPage', 'hiddenLateBody', '{amount} pro Minute nach achtzehn Uhr, in vollen Minuten berechnet und der nächsten Rechnung zugeschlagen. Das ist keine Strafe; es ist, was es kostet, zwei Mitarbeitende im Haus zu halten, und zwei sind das Minimum, das die Lizenz erlaubt.'),
  ('de', 'TuitionPage', 'hiddenLateTitle', 'Verspätetes Abholen'),
  ('de', 'TuitionPage', 'hiddenSiblingBody', '{percent}% Nachlass auf den Satz des jüngeren Kindes, automatisch, solange beide angemeldet sind. Sie müssen nicht danach fragen, und niemand muss daran denken, ihn einzutragen.'),
  ('de', 'TuitionPage', 'hiddenSiblingTitle', 'Zwei Kinder bei uns'),
  ('de', 'TuitionPage', 'intro', 'Bei den meisten Einrichtungen müssen Sie dafür anrufen. Uns ist lieber, Sie sehen die Zahl jetzt und entscheiden, ob sie einen Anruf wert ist, als dass Sie es am Ende einer Führung erfahren, für die Sie einen Vormittag aufgewendet haben. Jeder Satz, den wir verlangen, steht auf dieser Seite.'),
  ('de', 'TuitionPage', 'metaDescription', 'Was Kinderbetreuung in Northwest Portland wirklich kostet — Monatssätze für jede Gruppe und jedes Modell, offen auf der Seite, samt der Kosten, die eine Preisliste sonst weglässt.'),
  ('de', 'TuitionPage', 'metaTitle', 'Gebühren'),
  ('de', 'TuitionPage', 'ratesBody', 'Die Sätze gelten monatlich und ändern sich nicht mit der Länge des Monats — im Februar zahlen Sie dasselbe wie im März. Ein Teilzeitplatz kostet pro Tag mehr als ein Vollzeitplatz, weil die Gruppe die ganze Woche besetzt ist, ob Ihr Kind an dem Tag da ist oder nicht.'),
  ('de', 'TuitionPage', 'ratesFootnote', 'Die Sätze werden einmal im Jahr im September überprüft, und wir teilen es Ihnen schriftlich bis zum Juni davor mit — nie mitten im Jahr und nie mit weniger als einem Halbjahr Vorlauf.'),
  ('de', 'TuitionPage', 'ratesHeading', 'Monatssätze'),
  ('de', 'TuitionPage', 'ratesRoom', 'Gruppe'),
  ('de', 'TuitionPage', 'ratesTableCaption', 'Monatsgebühren nach Gruppe und Modell'),
  ('de', 'TuitionPage', 'schedulesBody', 'Drei Modelle, an festen Tagen. Sie können wechseln, sobald im gewünschten Modell ein Platz frei wird, und behalten währenddessen Ihren Platz auf der Liste.'),
  ('de', 'TuitionPage', 'schedulesHeading', 'Betreuungsmodelle'),
  ('de', 'TuitionPage', 'schedulesSwitching', 'Ein Wechsel braucht einen Monat Vorlauf und einen freien Platz in der Gruppe an den Tagen, auf die Sie wechseln. Wir sagen Ihnen ehrlich, ob das Wochen entfernt ist oder fast ein Jahr.'),
  ('de', 'TuitionPage', 'threeDayBody', 'Feste Tage statt Tage, die Sie jede Woche neu wählen, damit Ihr Kind weiß, welche Morgen ihm gehören, und die Gruppe beständig bleibt. Die meisten Familien in diesem Modell teilen sich die Woche mit den Großeltern.'),
  ('de', 'TuitionPage', 'threeDayDays', 'Montag, Mittwoch, Freitag'),
  ('de', 'TuitionPage', 'threeDayName', 'Drei Tage'),
  ('de', 'TuitionPage', 'twoDayBody', 'Genug, um eine Routine und eine Freundschaft zu halten, ohne die ganze Woche. Plätze in diesem Modell sind die knappsten, die wir haben, weil zwei davon einen Vollzeitplatz füllen und beide zusammenpassen müssen.'),
  ('de', 'TuitionPage', 'twoDayDays', 'Dienstag und Donnerstag'),
  ('de', 'TuitionPage', 'twoDayName', 'Zwei Tage'),
  ('de', 'TuitionPage', 'visitBody', 'Sie haben die Zahlen, und das ist das meiste von dem, was eine Führung Ihnen über Geld gesagt hätte. Offen bleibt, ob der Raum es wert ist, und genau das kann eine Preisliste Ihnen nicht zeigen.'),
  ('de', 'TuitionPage', 'visitHeading', 'Vor der Entscheidung einen Anruf wert'),
  ('de', 'Visit', 'askLabel', 'Fragen Sie nach'),
  ('de', 'Visit', 'askValue', 'Maria, der Leiterin'),
  ('de', 'Visit', 'bookingLabel', 'Anmeldung'),
  ('de', 'Visit', 'bookingValue', 'Kein Termin nötig'),
  ('de', 'Visit', 'call', 'Anrufen'),
  ('de', 'Visit', 'cardHeading', 'So läuft ein Besuch ab'),
  ('de', 'Visit', 'lengthLabel', 'Wie lange es dauert'),
  ('de', 'Visit', 'lengthValue', 'Etwa zwanzig Minuten'),
  ('de', 'Visit', 'whenLabel', 'Beste Zeit zum Kommen'),
  ('de', 'Visit', 'whenValue', 'Zehn Uhr morgens, wenn die Gruppen laufen'),
  ('en', 'AboutPage', 'eyebrow', 'Licensed since {since}'),
  ('en', 'AboutPage', 'heading', 'How we care for children, and why'),
  ('en', 'AboutPage', 'intro', 'A center is easy to describe well and hard to run well. This page is the second thing — how the rooms are staffed, what the license behind the front door actually covers, and what happens on the ordinary days nobody writes a brochure about.'),
  ('en', 'AboutPage', 'licensingBody', 'We have held a state child care license continuously since {since}. A license is not a certificate on a wall; it is an inspection regime, and we would rather you know exactly what it covers before you ask.'),
  ('en', 'AboutPage', 'licensingCoversBuilding', 'Building, playground, exits, and drills'),
  ('en', 'AboutPage', 'licensingCoversHeading', 'What an inspection covers'),
  ('en', 'AboutPage', 'licensingCoversKitchen', 'The kitchen, food handling, and allergy practice'),
  ('en', 'AboutPage', 'licensingCoversRatios', 'Ratios and supervision, room by room'),
  ('en', 'AboutPage', 'licensingCoversRecords', 'Staff files, clearances, and training records'),
  ('en', 'AboutPage', 'licensingCoversSleep', 'Safe sleep, cots, and nap routines'),
  ('en', 'AboutPage', 'licensingHeading', 'Licensing and the checks behind it'),
  ('en', 'AboutPage', 'licensingInspectionsLabel', 'Inspections'),
  ('en', 'AboutPage', 'licensingInspectionsValue', 'Unannounced, at least annually'),
  ('en', 'AboutPage', 'licensingNumberLabel', 'State license'),
  ('en', 'AboutPage', 'licensingRecords', 'The state keeps our full inspection history, and you are entitled to read it. Ask at the office and we will show you ours, findings included.'),
  ('en', 'AboutPage', 'licensingSinceLabel', 'Licensed since'),
  ('en', 'AboutPage', 'licensingStaffLine', 'Every member of staff is background-checked before their first day with children, and holds current CPR and first aid certification — the director included.'),
  ('en', 'AboutPage', 'metaDescription', 'A licensed child care center in Northwest Portland since {since} — our approach, our ratios, our state license, and what safety looks like on an ordinary day.'),
  ('en', 'AboutPage', 'metaTitle', 'About'),
  ('en', 'AboutPage', 'philosophyHeading', 'What we believe'),
  ('en', 'AboutPage', 'philosophyKnownBody', 'Every child has a primary caregiver, and teachers stay with their room for the year. It is why we can tell you at pickup that your son ate half his lunch and then fell asleep on the reading cushion — someone was there for all of it.'),
  ('en', 'AboutPage', 'philosophyKnownTitle', 'A child should be known by a few people, not minded by many'),
  ('en', 'AboutPage', 'philosophyPlainBody', 'If your child bit someone, we will tell you. If a room is full and the wait is nine months, we will say nine months rather than let you hope. You cannot leave your child somewhere you have caught being vague.'),
  ('en', 'AboutPage', 'philosophyPlainTitle', 'Parents get the truth, including the parts that are hard'),
  ('en', 'AboutPage', 'philosophyRhythmBody', 'The same rhythm every day — arrival, breakfast, circle, outside, lunch, rest. A child who knows what comes next has the confidence to be inventive inside it. Structure is what makes the mess possible.'),
  ('en', 'AboutPage', 'philosophyRhythmTitle', 'The day should be predictable, the play should not'),
  ('en', 'AboutPage', 'ratiosAges', 'Ages'),
  ('en', 'AboutPage', 'ratiosBody', 'These are the numbers we staff to every hour we are open, not an average across the week. Both matter: the ratio is how much attention your child gets, and the group size is how loud and how busy the room is around them.'),
  ('en', 'AboutPage', 'ratiosFootnote', 'Our ratios are at or below what the state requires for each age, and we hold them through nap, lunch, and the end of the day — the hours a ratio is easiest to quietly let slip.'),
  ('en', 'AboutPage', 'ratiosGroup', 'Group size'),
  ('en', 'AboutPage', 'ratiosHeading', 'Ratios and group sizes'),
  ('en', 'AboutPage', 'ratiosRatio', 'Ratio'),
  ('en', 'AboutPage', 'ratiosRoom', 'Room'),
  ('en', 'AboutPage', 'ratiosTableCaption', 'Staffing ratio and group size by room'),
  ('en', 'AboutPage', 'safetyAllergyBody', 'Allergies are posted in the room and in the kitchen, meals are made on site so we control what is in them, and medication is given only with your written instruction and logged when it is.'),
  ('en', 'AboutPage', 'safetyAllergyTitle', 'Allergies and medication'),
  ('en', 'AboutPage', 'safetyBody', 'Most of safety is not dramatic. It is the same small routines done the same way every day, by people who are not improvising.'),
  ('en', 'AboutPage', 'safetyDrillsBody', 'Fire drills monthly and emergency procedures quarterly, with the children, so the routine is familiar to them rather than frightening.'),
  ('en', 'AboutPage', 'safetyDrillsTitle', 'Practised, not planned'),
  ('en', 'AboutPage', 'safetyEntryBody', 'A single entrance with a keypad code, changed each term. Nobody who is not on your child''s authorized list leaves with them — no exceptions made at the door, ever, however plausible the person seems.'),
  ('en', 'AboutPage', 'safetyEntryTitle', 'One locked door'),
  ('en', 'AboutPage', 'safetyHeading', 'Safety, on an ordinary day'),
  ('en', 'AboutPage', 'safetyIllnessBody', 'Fever, vomiting, or anything contagious means going home and staying home for twenty-four clear hours. It is inconvenient, and it is the reason the whole room is not sick next week.'),
  ('en', 'AboutPage', 'safetyIllnessTitle', 'Illness, said plainly'),
  ('en', 'AboutPage', 'safetySignInBody', 'Every child is signed in and out by name, and teachers count their group at every transition — into the room, out to the yard, back from the yard.'),
  ('en', 'AboutPage', 'safetySignInTitle', 'Signed in and counted'),
  ('en', 'AboutPage', 'visitAria', 'Plan a visit'),
  ('en', 'AboutPage', 'visitBody', 'None of this is worth much on a screen. Every center looks calm at nap time; what you want to see is a room with children awake in it, and the only way to see that is to be standing in one.'),
  ('en', 'AboutPage', 'visitHeading', 'The part that matters is standing in the room'),
  ('en', 'Center', 'ageRange', '6 weeks to 5 years'),
  ('en', 'Center', 'hoursCompact', '7am–6pm'),
  ('en', 'Center', 'hoursShort', 'Mon–Fri, 7:00 AM – 6:00 PM'),
  ('en', 'Center', 'neighborhood', 'Northwest Portland, one block from Wallace Park'),
  ('en', 'ContactPage', 'callBody', 'One number reaches all of it. Saying which of these it is when someone picks up gets you to the right person faster.'),
  ('en', 'ContactPage', 'callHeading', 'What to call about, and who you will get'),
  ('en', 'ContactPage', 'callHoursBody', 'Voicemail after six, picked up when the office opens at seven the next morning. Nothing is answered overnight, so if it cannot wait until then, it should not be a message.'),
  ('en', 'ContactPage', 'callHoursTitle', 'Outside opening hours'),
  ('en', 'ContactPage', 'callIllnessBody', 'Call before nine so the room can plan its morning. Tell us the symptom rather than the diagnosis; whether it is a twenty-four-hour exclusion is our job to work out, not yours.'),
  ('en', 'ContactPage', 'callIllnessTitle', 'Your child is unwell today'),
  ('en', 'ContactPage', 'callPlaceBody', 'Ask for Nadia, who keeps the waiting list. She will tell you which rooms have space and, if the one you want does not, how long the wait honestly is — including when the answer is most of a year.'),
  ('en', 'ContactPage', 'callPlaceTitle', 'A place for your child'),
  ('en', 'ContactPage', 'drivingBody', 'Four marked spaces beside the building are reserved for drop-off and pickup, fifteen minutes each. Street parking on the block is unrestricted, and the far end is usually open even at half past eight.'),
  ('en', 'ContactPage', 'drivingTitle', 'Driving and parking'),
  ('en', 'ContactPage', 'emailNote', 'Email is read once a day, in the afternoon. For anything about a place, a start date, or a child who is unwell, please call — you will get an answer in the same conversation rather than tomorrow.'),
  ('en', 'ContactPage', 'eyebrow', 'One number, one address'),
  ('en', 'ContactPage', 'factAddressLabel', 'Address'),
  ('en', 'ContactPage', 'factClosedLabel', 'Closed'),
  ('en', 'ContactPage', 'factClosedValue', 'Weekends and public holidays'),
  ('en', 'ContactPage', 'factEmailLabel', 'Email'),
  ('en', 'ContactPage', 'factHoursLabel', 'Open'),
  ('en', 'ContactPage', 'footBody', 'One block from Wallace Park, with a covered bike rack inside the gate. Buggies and strollers go in the entry hall rather than the rooms — there is space for them, and it keeps the doorways clear.'),
  ('en', 'ContactPage', 'footTitle', 'On foot and by bike'),
  ('en', 'ContactPage', 'gettingHereBody', 'We are on a residential block, which is lovely at eight in the morning and awkward if you are circling for a space. Here is what the school run actually looks like, so your first drop-off is not also your first time working it out.'),
  ('en', 'ContactPage', 'gettingHereHeading', 'Getting here'),
  ('en', 'ContactPage', 'heading', 'Call us, or come and stand in the room'),
  ('en', 'ContactPage', 'intro', 'The phone is answered by someone who works here, not a service, and you will get a plain answer about space and waiting lists on the first call. Everything you need to reach us or find us is on this page.'),
  ('en', 'ContactPage', 'mapLabel', 'Map placeholder — {address}'),
  ('en', 'ContactPage', 'metaDescription', 'Call, email, or visit a licensed child care center in Northwest Portland — phone, address, opening hours, parking, and how to get here by bus, bike, or on foot.'),
  ('en', 'ContactPage', 'metaTitle', 'Contact'),
  ('en', 'ContactPage', 'transitBody', 'The nearest bus stop is a three-minute walk, and the streetcar line is about eight minutes on foot. Both leave you on the park side of the street, so you cross once and away from traffic.'),
  ('en', 'ContactPage', 'transitTitle', 'By bus or streetcar'),
  ('en', 'ContactPage', 'visitBody', 'You have the number and you know where we are. What is left is the part no page can do for you: standing in a room on an ordinary morning and deciding whether these are the people you want holding your child.'),
  ('en', 'ContactPage', 'visitHeading', 'The visit is the part that decides it'),
  ('en', 'Day', 'arrival', 'Arrival and free play'),
  ('en', 'Day', 'breakfast', 'Breakfast, then morning circle'),
  ('en', 'Day', 'centers', 'Learning centers and outdoor time'),
  ('en', 'Day', 'lunch', 'Lunch, made on site'),
  ('en', 'Day', 'nap', 'Nap and quiet rest'),
  ('en', 'Day', 'pickup', 'Outdoor play until pickup'),
  ('en', 'Day', 'snack', 'Snack and afternoon projects'),
  ('en', 'FaqPage', 'dailyFoodAnswer', 'Sofia cooks every meal on site, which is why we can be exact about an allergy rather than hopeful about a label. Allergies are posted in the kitchen and in the room, and we do not ask you to send a separate lunch.'),
  ('en', 'FaqPage', 'dailyFoodQuestion', 'Who cooks, and what about allergies?'),
  ('en', 'FaqPage', 'dailyHeading', 'Day to day'),
  ('en', 'FaqPage', 'dailyNappiesAnswer', 'On your child''s timeline and in step with whatever you are doing at home. We will never tell you a child has to be out of nappies to move rooms, and nobody is made to feel behind.'),
  ('en', 'FaqPage', 'dailyNappiesQuestion', 'How does toilet learning work?'),
  ('en', 'FaqPage', 'dailyOutsideAnswer', 'Yes, most days — this is Portland, and a year indoors waiting for dry weather is not a childhood. Send a coat and boots that you do not mind coming home unrecognisable.'),
  ('en', 'FaqPage', 'dailyOutsideQuestion', 'Do they go outside when it rains?'),
  ('en', 'FaqPage', 'dailyScreensAnswer', 'No screens in any room, at any age. Not as a rule we are proud of, just one we have never needed to break.'),
  ('en', 'FaqPage', 'dailyScreensQuestion', 'Is there screen time?'),
  ('en', 'FaqPage', 'dailySleepAnswer', 'They rest quietly with a book instead. No child is kept on a cot for two hours because the room has a nap time, and no child is woken because pickup is coming.'),
  ('en', 'FaqPage', 'dailySleepQuestion', 'What if our child does not nap?'),
  ('en', 'FaqPage', 'eyebrow', '{count} questions, answered'),
  ('en', 'FaqPage', 'factAgesLabel', 'Ages we take'),
  ('en', 'FaqPage', 'factCountLabel', 'Questions answered here'),
  ('en', 'FaqPage', 'factMissingLabel', 'Not on this list'),
  ('en', 'FaqPage', 'factMissingValue', 'Call and ask — it gets added'),
  ('en', 'FaqPage', 'factSourceLabel', 'Where these came from'),
  ('en', 'FaqPage', 'factSourceValue', 'The office phone, over about a year'),
  ('en', 'FaqPage', 'heading', 'The questions parents actually ask'),
  ('en', 'FaqPage', 'intro', 'These are taken from the phone, not invented for a website. They include the awkward ones — what happens when a child bites, how to complain about us — because those are the ones you cannot ask on a tour without feeling rude, and they are the ones worth knowing the answer to.'),
  ('en', 'FaqPage', 'metaDescription', 'The questions parents actually ask a licensed child care center in Northwest Portland — waiting lists, settling in, food and allergies, illness, and what happens when something goes wrong.'),
  ('en', 'FaqPage', 'metaTitle', 'FAQ'),
  ('en', 'FaqPage', 'placeAheadAnswer', 'For the infant room, as soon as you are ready to tell people you are expecting — that room runs six to nine months behind. Toddler and preschool places move faster, often within a term.'),
  ('en', 'FaqPage', 'placeAheadQuestion', 'How far ahead should we apply?'),
  ('en', 'FaqPage', 'placeDaysAnswer', 'You choose a schedule rather than individual days: five days, Monday–Wednesday–Friday, or Tuesday–Thursday. Fixed days mean your child has the same group around them each time, which is most of what makes them settle.'),
  ('en', 'FaqPage', 'placeDaysQuestion', 'Can we choose which days?'),
  ('en', 'FaqPage', 'placeHeading', 'Getting a place'),
  ('en', 'FaqPage', 'placeHoldAnswer', 'Yes, for up to two months, with the deposit paid. Longer than that and we would be holding an empty room a family on the list needs, so we would rather put you back near the top for the month you actually want.'),
  ('en', 'FaqPage', 'placeHoldQuestion', 'Can we hold a place for a later start?'),
  ('en', 'FaqPage', 'placeWaitlistAnswer', 'It is by room and by date you joined, not by who calls most. When a space comes up we work down the list and you get about a week to decide. Nobody moves up for paying more, and there is nothing to pay to be on it.'),
  ('en', 'FaqPage', 'placeWaitlistQuestion', 'How does the waiting list work?'),
  ('en', 'FaqPage', 'startingBringAnswer', 'A change of clothes, a coat that can get muddy, and whatever your child sleeps with. Not nappies, wipes, sunscreen, or food — those are in the rate, so nobody is scrambling at seven in the morning.'),
  ('en', 'FaqPage', 'startingBringQuestion', 'What do we need to bring?'),
  ('en', 'FaqPage', 'startingHeading', 'Starting here'),
  ('en', 'FaqPage', 'startingHearAnswer', 'Under threes get the day written down — every bottle, nap, and nappy — handed to you at pickup. Older children get it told to you at the door by the teacher who was actually with them, which is more use than a form.'),
  ('en', 'FaqPage', 'startingHearQuestion', 'How will we hear about our child''s day?'),
  ('en', 'FaqPage', 'startingSettleAnswer', 'Two short visits with you in the room before the start date, then a half day, then a full one. Some children skip straight to the full day and some need a fortnight, and neither is a problem — we follow your child rather than the plan.'),
  ('en', 'FaqPage', 'startingSettleQuestion', 'What does the first week look like?'),
  ('en', 'FaqPage', 'troubleBitingAnswer', 'Both sets of parents are told the same day, and neither child is named to the other family. Biting is normal in a toddler room and it is our job to shadow and redirect, not to ask a two-year-old to explain themselves.'),
  ('en', 'FaqPage', 'troubleBitingQuestion', 'What if our child bites, or is bitten?'),
  ('en', 'FaqPage', 'troubleComplaintAnswer', 'Tell Maria directly and you will get an answer within two days. If that does not settle it, the state licensing office takes complaints about us without going through us at all, and we will give you the number ourselves.'),
  ('en', 'FaqPage', 'troubleComplaintQuestion', 'How do we complain about you?'),
  ('en', 'FaqPage', 'troubleHeading', 'When something goes wrong'),
  ('en', 'FaqPage', 'troubleInjuryAnswer', 'Anything above a scraped knee gets a phone call while it is happening, not a note at pickup. Every injury is written up and you sign the record, including the ones that turned out to be nothing.'),
  ('en', 'FaqPage', 'troubleInjuryQuestion', 'What happens if our child is hurt?'),
  ('en', 'FaqPage', 'troubleSickAnswer', 'Fever, vomiting, or anything contagious means going home and staying home for twenty-four clear hours after it stops. It is genuinely inconvenient, and it is the reason the whole room is not unwell the following week.'),
  ('en', 'FaqPage', 'troubleSickQuestion', 'When is a child too unwell to come?'),
  ('en', 'FaqPage', 'visitBody', 'A list like this answers the questions we have already been asked. Yours may not be here, and the fastest way through it is standing in the building asking a person who can say “I do not know, let me find out” rather than picking from a page.'),
  ('en', 'FaqPage', 'visitHeading', 'Ask us the rest in person'),
  ('en', 'Footer', 'tagline', 'Licensed child care facility · State license {licenseNumber} · Serving families since {since}.'),
  ('en', 'HomePage', 'contactAddress', 'Address'),
  ('en', 'HomePage', 'contactHours', 'Hours'),
  ('en', 'HomePage', 'contactPhone', 'Phone'),
  ('en', 'HomePage', 'dayBody', 'Predictable rhythm, room to be a kid. Here is what nine hours actually looks like.'),
  ('en', 'HomePage', 'dayHeading', 'A day at Willow Grove'),
  ('en', 'HomePage', 'heroBody', 'A small, licensed center in {neighborhood}, where the same caregivers greet your child every morning and can tell you exactly how their day went.'),
  ('en', 'HomePage', 'heroEyebrow', 'Licensed child care · Ages {ageRange}'),
  ('en', 'HomePage', 'heroHeading', 'A place where your child is known by name.'),
  ('en', 'HomePage', 'infantsBlurb', 'One primary caregiver per child, so feeds, naps, and first words are tracked by someone who knows your baby — not whoever is free.'),
  ('en', 'HomePage', 'mapLabel', 'Map of {neighborhood}'),
  ('en', 'HomePage', 'metaDescription', 'A small, licensed child care center in Northwest Portland for ages 6 weeks to 5 years, where the same caregivers know your child by name. Call to plan a visit.'),
  ('en', 'HomePage', 'metaTitle', 'Willow Grove Children''s Center · Licensed child care in NW Portland'),
  ('en', 'HomePage', 'planVisit', 'Plan a visit'),
  ('en', 'HomePage', 'preschoolBlurb', 'Early literacy, numbers, and the harder work of taking turns and naming feelings — the groundwork for kindergarten.'),
  ('en', 'HomePage', 'programsHeading', 'Programs by age'),
  ('en', 'HomePage', 'staffHeading', 'The people who will know your child'),
  ('en', 'HomePage', 'testimonialAttribution', 'Priya R., parent of an infant-room child'),
  ('en', 'HomePage', 'testimonialHeading', 'From a parent'),
  ('en', 'HomePage', 'testimonialQuote', '“On day three, Aisha told me my daughter only settles for her nap if she can hold the blue elephant. I hadn''t told anyone that. That''s when I stopped worrying.”'),
  ('en', 'HomePage', 'toddlersBlurb', 'Room to move and language everywhere. Days are predictable so a toddler learning the world can count on what comes next.'),
  ('en', 'HomePage', 'trustInfantRatio', 'Infant ratio'),
  ('en', 'HomePage', 'trustOpenWeekdays', 'Open weekdays'),
  ('en', 'HomePage', 'trustStateLicense', 'State license'),
  ('en', 'HomePage', 'trustYearsCaring', 'Caring for families'),
  ('en', 'HomePage', 'visitHeading', 'Come see it for yourself'),
