  ('en', 'Nav', 'about', 'About'),
  ('en', 'Nav', 'contact', 'Contact'),
  ('en', 'Nav', 'faq', 'FAQ'),
  ('en', 'Nav', 'home', 'Willow Grove home'),
  ('en', 'Nav', 'programs', 'Programs'),
  ('en', 'Nav', 'staff', 'Staff'),
  ('en', 'Nav', 'tuition', 'Tuition'),
  ('en', 'Programs', 'infants', 'Infants'),
  ('en', 'Programs', 'infantsAges', '6 weeks – 15 months'),
  ('en', 'Programs', 'infantsGroupSize', '8 children'),
  ('en', 'Programs', 'preschool', 'Preschool'),
  ('en', 'Programs', 'preschoolAges', '3 – 5 years'),
  ('en', 'Programs', 'preschoolGroupSize', '18 children'),
  ('en', 'Programs', 'toddlers', 'Toddlers'),
  ('en', 'Programs', 'toddlersAges', '15 months – 3 years'),
  ('en', 'Programs', 'toddlersGroupSize', '10 children'),
  ('en', 'ProgramsPage', 'dayBody', 'Every room runs on the same rhythm, scaled to the age. Infants sleep and eat on their own schedule inside it; older children move through it together.'),
  ('en', 'ProgramsPage', 'dayHeading', 'A day at Willow Grove'),
  ('en', 'ProgramsPage', 'eyebrow', 'Ages {ageRange}'),
  ('en', 'ProgramsPage', 'factAges', 'Ages'),
  ('en', 'ProgramsPage', 'factGroup', 'Group size'),
  ('en', 'ProgramsPage', 'factRatio', 'Ratio'),
  ('en', 'ProgramsPage', 'heading', 'Programs by age'),
  ('en', 'ProgramsPage', 'infantsDetail', 'Every baby is assigned one primary caregiver who handles their feeds, naps, and nappies. That is the person who learns that your daughter will only go down holding the blue elephant, and the person who tells you about it at pickup.'),
  ('en', 'ProgramsPage', 'infantsStaffing', 'Feeds and sleep follow your baby''s schedule, not the room''s. You get the day written down — every bottle, every nap, every nappy — before you reach the car park.'),
  ('en', 'ProgramsPage', 'intro', 'Three rooms in one building, and the same faces from the infant room to the morning your child leaves for kindergarten. Here is who is in each room, how many children they care for, and what the day holds.'),
  ('en', 'ProgramsPage', 'metaDescription', 'Infant, toddler, and preschool rooms in Northwest Portland — ratios, group sizes, and what a day actually looks like in each room.'),
  ('en', 'ProgramsPage', 'metaTitle', 'Programs'),
  ('en', 'ProgramsPage', 'preschoolDetail', 'Early literacy and numbers, and the harder curriculum underneath them — taking turns, waiting, saying what you feel instead of throwing something. This is the groundwork kindergarten expects a child to arrive with.'),
  ('en', 'ProgramsPage', 'preschoolStaffing', 'Small-group work every morning, led by a teacher who has taught this room for years. In the spring we write to your child''s kindergarten so their first teacher starts already knowing them.'),
  ('en', 'ProgramsPage', 'toddlersDetail', 'The year a child learns that the world has an order to it. Days are deliberately predictable, so a toddler who cannot yet tell time can still tell what comes next, and the language never stops — naming, narrating, asking.'),
  ('en', 'ProgramsPage', 'toddlersStaffing', 'Two teachers stay with this room all year. Toilet learning happens on your child''s timeline and in step with what you are doing at home, never on a deadline we set.'),
  ('en', 'ProgramsPage', 'visitAria', 'Plan a visit'),
  ('en', 'ProgramsPage', 'visitBody', 'Call the office and you will get a plain answer about which rooms have space and what the wait looks like for the ones that do not — then come and stand in the room your child would actually be in.'),
  ('en', 'ProgramsPage', 'visitHeading', 'Not sure which room fits?'),
  ('en', 'Staff', 'aishaBio', 'Eight years in the infant room and she has never once handed a parent a day sheet she had to guess at. She is the reason we can tell you which side your daughter prefers to be held on.'),
  ('en', 'Staff', 'aishaRole', 'Lead Infant Teacher'),
  ('en', 'Staff', 'danielBio', 'Spends his day narrating the world to people who have just discovered it has words. Toilet learning happens on his watch, on your child''s timeline, and he will never make you feel behind.'),
  ('en', 'Staff', 'danielRole', 'Lead Toddler Teacher'),
  ('en', 'Staff', 'graceBio', 'Came to us from a hospital nursery, which shows in how she handles a baby who will not settle. She has the calmest hands in the building and the room is quieter for it.'),
  ('en', 'Staff', 'graceRole', 'Infant Teacher'),
  ('en', 'Staff', 'mariaBio', 'Runs the place, and still covers the infant room when someone is off sick. She is the one you will be handed to when you call, and the one who will tell you plainly if the room you want has a nine-month wait.'),
  ('en', 'Staff', 'mariaRole', 'Director'),
  ('en', 'Staff', 'nadiaBio', 'Handles enrolment, the waiting list, and every piece of paper the state asks for. If you have ever been given a vague answer about fees somewhere else, she is the correction to that.'),
  ('en', 'Staff', 'nadiaRole', 'Assistant Director'),
  ('en', 'Staff', 'sofiaBio', 'Cooks every meal on site, which is why we can be exact about allergies rather than hopeful. She knows which children will eat a vegetable only if it is cut a particular way, and cuts it that way.'),
  ('en', 'Staff', 'sofiaRole', 'Cook'),
  ('en', 'Staff', 'tenure', 'with Willow Grove {years} years'),
  ('en', 'Staff', 'tomBio', 'Teaches the small-group work every morning and writes to each child''s kindergarten in the spring, so their first teacher starts already knowing them. Six years in the same room.'),
  ('en', 'Staff', 'tomRole', 'Lead Preschool Teacher'),
  ('en', 'StaffPage', 'eyebrow', '{count} teachers and staff'),
  ('en', 'StaffPage', 'factChecksLabel', 'Every hire'),
  ('en', 'StaffPage', 'factChecksValue', 'Background-checked, CPR and first aid current'),
  ('en', 'StaffPage', 'factLongestLabel', 'Longest with us'),
  ('en', 'StaffPage', 'factTeamLabel', 'Teachers and staff'),
  ('en', 'StaffPage', 'factTenureLabel', 'Average time with us'),
  ('en', 'StaffPage', 'heading', 'The people who will know your child'),
  ('en', 'StaffPage', 'intro', 'The tour tells you about the building. This page tells you about the people in it, because a room is only as steady as whoever is standing in it — and how long they have stayed is the one thing a brochure cannot fake.'),
  ('en', 'StaffPage', 'metaDescription', 'The teachers and staff at a licensed child care center in Northwest Portland — who they are, how long they have been here, and why that is the number to compare.'),
  ('en', 'StaffPage', 'metaTitle', 'Staff'),
  ('en', 'StaffPage', 'stayBody', 'Turnover is the thing that quietly wrecks a center, and it is almost never mentioned on a website. Here is what we do about it, so you can ask the next center you visit the same three questions.'),
  ('en', 'StaffPage', 'stayHeading', 'Why people stay'),
  ('en', 'StaffPage', 'stayHiringBody', 'A vacancy is covered by the director and the assistant director rather than filled quickly. Every hire is background-checked before their first day with children, with no exceptions for busy weeks.'),
  ('en', 'StaffPage', 'stayHiringTitle', 'Slow to hire, on purpose'),
  ('en', 'StaffPage', 'stayPayBody', 'Teachers are paid above what centers around us pay, and the pay rises with time here rather than with a job title. It is the largest thing on our cost sheet and the reason tuition is what it is.'),
  ('en', 'StaffPage', 'stayPayTitle', 'Paid above the going rate, deliberately'),
  ('en', 'StaffPage', 'stayRoomBody', 'Nobody is moved between rooms to plug a gap. A teacher stays with their group for the year, which is what makes a primary caregiver mean anything beyond a word on a page.'),
  ('en', 'StaffPage', 'stayRoomTitle', 'The same room, all year'),
  ('en', 'StaffPage', 'teamBody', 'Portraits are coming; the initials are a placeholder, not a stock photo of somebody else''s staff. Everything under each name is true of the person who will actually be in the room.'),
  ('en', 'StaffPage', 'teamHeading', 'Who is here'),
  ('en', 'StaffPage', 'visitBody', 'Names on a page are not much use. Come and watch the room your child would be in, and see whether the person in it looks like someone your child would settle with.'),
  ('en', 'StaffPage', 'visitHeading', 'Come and meet them'),
  ('en', 'StaffPage', 'yearsValue', '{years} years'),
  ('en', 'TuitionPage', 'eyebrow', 'From {lowest} a month, full time'),
  ('en', 'TuitionPage', 'factDepositLabel', 'Deposit'),
  ('en', 'TuitionPage', 'factDepositValue', '{weeks} weeks, refundable when you leave'),
  ('en', 'TuitionPage', 'factIncludedLabel', 'Included in the rate'),
  ('en', 'TuitionPage', 'factIncludedValue', 'Meals, snacks, nappies, wipes, and sunscreen'),
  ('en', 'TuitionPage', 'factNoticeLabel', 'Notice to leave'),
  ('en', 'TuitionPage', 'factNoticeValue', '{weeks} weeks, in writing'),
  ('en', 'TuitionPage', 'factRegistrationLabel', 'Registration'),
  ('en', 'TuitionPage', 'factRegistrationValue', '{amount}, once, at enrolment'),
  ('en', 'TuitionPage', 'fiveDayBody', 'The full week, and the only schedule where your child has the same group around them every day. It is what we recommend for infants, who settle faster when the week does not keep changing shape.'),
  ('en', 'TuitionPage', 'fiveDayDays', 'Monday to Friday'),
  ('en', 'TuitionPage', 'fiveDayName', 'Five days'),
  ('en', 'TuitionPage', 'heading', 'What a place here costs'),
  ('en', 'TuitionPage', 'hiddenBody', 'None of this is buried in a contract you sign on the last day. It is here, before you call, because the cost of child care is not only the number in the table.'),
  ('en', 'TuitionPage', 'hiddenClosuresBody', 'Public holidays, plus three staff training days a year and the week between Christmas and New Year. Those are charged — the rate is monthly, not per day attended — and the dates are published each August, a year ahead.'),
  ('en', 'TuitionPage', 'hiddenClosuresTitle', 'Days we are closed'),
  ('en', 'TuitionPage', 'hiddenHeading', 'The parts a rate sheet usually leaves out'),
  ('en', 'TuitionPage', 'hiddenHelpBody', 'We accept state subsidy and take dependent-care benefits from employers. Nadia handles both, and she will tell you what you are likely to qualify for before you fill in anything — including when the answer is nothing.'),
  ('en', 'TuitionPage', 'hiddenHelpTitle', 'Help with the cost'),
  ('en', 'TuitionPage', 'hiddenIncreaseBody', 'Rates go up once a year and it is usually a few per cent, tracking what we pay teachers. You get it in writing in June for a September start, so nobody is surprised by an invoice.'),
  ('en', 'TuitionPage', 'hiddenIncreaseTitle', 'The annual increase'),
  ('en', 'TuitionPage', 'hiddenLateBody', '{amount} a minute after six, charged in whole minutes and added to the next invoice. It is not a punishment; it is what it costs to keep two members of staff in the building, and two is the minimum the license allows.'),
  ('en', 'TuitionPage', 'hiddenLateTitle', 'Late pickup'),
  ('en', 'TuitionPage', 'hiddenSiblingBody', '{percent}% off the younger child''s rate, applied automatically for as long as both are enrolled. You do not have to ask for it, and nobody has to remember to add it.'),
  ('en', 'TuitionPage', 'hiddenSiblingTitle', 'Two children here'),
  ('en', 'TuitionPage', 'intro', 'Most centers make you call for this. We would rather you saw the number now and decided whether it is worth a phone call, than found out at the end of a tour you spent a morning on. Every rate we charge is on this page.'),
  ('en', 'TuitionPage', 'metaDescription', 'What child care actually costs in Northwest Portland — monthly rates for every room and schedule, published on the page, plus the fees a rate sheet usually leaves out.'),
  ('en', 'TuitionPage', 'metaTitle', 'Tuition'),
  ('en', 'TuitionPage', 'ratesBody', 'Rates are monthly and do not change with the length of the month — you pay the same in February as in March. A part-time place costs more per day than a full-time one, because the room is staffed for the whole week whether or not your child is in it that day.'),
  ('en', 'TuitionPage', 'ratesFootnote', 'Rates are reviewed once a year, in September, and we tell you in writing by the preceding June — never mid-year, and never with less than a term''s warning.'),
  ('en', 'TuitionPage', 'ratesHeading', 'Monthly rates'),
  ('en', 'TuitionPage', 'ratesRoom', 'Room'),
  ('en', 'TuitionPage', 'ratesTableCaption', 'Monthly tuition by room and schedule'),
  ('en', 'TuitionPage', 'schedulesBody', 'Three schedules, on fixed days. You can move between them when a place opens in the one you want, and you keep your spot on the list while you wait.'),
  ('en', 'TuitionPage', 'schedulesHeading', 'Schedule options'),
  ('en', 'TuitionPage', 'schedulesSwitching', 'Changing schedule needs a month''s notice and a place in the room on the days you are moving to. We will tell you honestly whether that is weeks away or most of a year.'),
  ('en', 'TuitionPage', 'threeDayBody', 'Fixed days rather than days you pick each week, so your child knows which mornings are theirs and the room can hold a consistent group. Most families on this schedule are splitting the week with a grandparent.'),
  ('en', 'TuitionPage', 'threeDayDays', 'Monday, Wednesday, Friday'),
  ('en', 'TuitionPage', 'threeDayName', 'Three days'),
  ('en', 'TuitionPage', 'twoDayBody', 'Enough to keep a routine and a friendship going without a full week. Places on this schedule are the scarcest we have, because two of them fill one full-time space and both have to line up.'),
  ('en', 'TuitionPage', 'twoDayDays', 'Tuesday and Thursday'),
  ('en', 'TuitionPage', 'twoDayName', 'Two days'),
  ('en', 'TuitionPage', 'visitBody', 'You have the numbers, which is most of what a tour would have told you about money. What is left is whether the room is worth it, and that is the one thing a rate sheet cannot show you.'),
  ('en', 'TuitionPage', 'visitHeading', 'Worth a call before you decide'),
  ('en', 'Visit', 'askLabel', 'Ask for'),
  ('en', 'Visit', 'askValue', 'Maria, the director'),
  ('en', 'Visit', 'bookingLabel', 'Booking'),
  ('en', 'Visit', 'bookingValue', 'No appointment needed'),
  ('en', 'Visit', 'call', 'Call'),
  ('en', 'Visit', 'cardHeading', 'What a visit looks like'),
  ('en', 'Visit', 'lengthLabel', 'How long it takes'),
  ('en', 'Visit', 'lengthValue', 'About twenty minutes'),
  ('en', 'Visit', 'whenLabel', 'Best time to come'),
  ('en', 'Visit', 'whenValue', 'Ten in the morning, while the rooms are running')
) as v (locale, namespace, key, value)
where o.slug = 'willow-grove'
on conflict (org_id, locale, namespace, key) where status = 'published'
